using System.Globalization;

namespace Editrainer;

/// <summary>
/// The app's own texts. Each is written in Spanish in the code, and that text is its key here.
/// Names of Pokémon, moves, abilities and items come from PKHeX in the language chosen.
/// </summary>
public static class Strings
{
    public sealed record Language(string Code, string Name, string GameData, string Font = "Segoe UI")
    {
        /// <summary>PKHeX has no game names in this language, so those stay in English.</summary>
        public bool EnglishNames => GameData == "en" && Code != "en";
        public override string ToString() => Name;
    }

    // Segoe UI has no Chinese, Japanese or Korean, and borrowing a font glyph by glyph gives uneven text.
    // PKHeX has no game data in Portuguese, Russian, Hindi or Arabic. Only Portuguese is offered, with English names.
    public static readonly Language[] Languages =
    [
        new("es", "Español", "es"), new("en", "English", "en"), new("zh", "简体中文", "zh-Hans", "Microsoft YaHei UI"), new("fr", "Français", "fr"),
        new("de", "Deutsch", "de"), new("it", "Italiano", "it"), new("ja", "日本語", "ja", "Yu Gothic UI"), new("ko", "한국어", "ko", "Malgun Gothic"),
        new("pt-BR", "Português (Brasil)", "en"),
    ];

    public static Language Current { get; private set; } = Languages[0];

    public static void Use(string code) => Current = Languages.FirstOrDefault(l => l.Code == code) ?? Languages[0];

    public static string T(string spanish) => !Table.TryGetValue(spanish, out var row) ? spanish : Current.Code switch {
        "en" => row.En, "zh" => row.Zh, "fr" => row.Fr, "de" => row.De,
        "it" => row.It, "ja" => row.Ja, "ko" => row.Ko, "pt-BR" => row.Pt,
        _ => spanish,
    };

    public static string T(string spanish, params object?[] values) => string.Format(CultureInfo.CurrentCulture, T(spanish), values);

    /// <summary>For the tests: every text, in the order of <see cref="Languages"/>.</summary>
    public static IEnumerable<string[]> AllTexts => Table.Select(row => new[] { row.Key, row.Value.En, row.Value.Zh, row.Value.Fr, row.Value.De, row.Value.It, row.Value.Ja, row.Value.Ko, row.Value.Pt });
    public static bool Has(string spanish) => Table.ContainsKey(spanish);

