        ["Este juego no usa habilidades."] = ("This game doesn’t use abilities.", "此游戏不使用特性。", "Ce jeu n’utilise pas les talents.", "Dieses Spiel hat keine Fähigkeiten.", "Questo gioco non ha abilità.", "このゲームにとくせいはありません。", "이 게임에는 특성이 없습니다.", "Este jogo não usa habilidades."),
        ["Este Pokémon solo tiene esta habilidad."] = ("This Pokémon only has this ability.", "这只宝可梦只有这一种特性。", "Ce Pokémon n’a que ce talent.", "Dieses Pokémon hat nur diese Fähigkeit.", "Questo Pokémon ha solo questa abilità.", "このポケモンのとくせいはこれだけです。", "이 포켓몬의 특성은 이것뿐입니다.", "Este Pokémon só tem esta habilidade."),
        ["{0}: sin límite total"] = ("{0}: no total limit", "{0}：无总量限制", "{0} : pas de limite totale", "{0}: kein Gesamtlimit", "{0}: nessun limite totale", "{0}：合計の上限なし", "{0}: 총합 제한 없음", "{0}: sem limite total"),
        ["EV: {0} / {1}  ·  Quedan {2}"] = ("EVs: {0} / {1}  ·  {2} left", "努力值：{0} / {1}  ·  剩余 {2}", "EV : {0} / {1}  ·  Reste {2}", "EV: {0} / {1}  ·  {2} übrig", "EV: {0} / {1}  ·  Ne restano {2}", "努力値：{0} / {1}  ·  残り {2}", "노력치: {0} / {1}  ·  {2} 남음", "EVs: {0} / {1}  ·  Restam {2}"),
        ["Este juego no tiene naturalezas."] = ("This game has no natures.", "此游戏没有性格。", "Ce jeu n’a pas de natures.", "Dieses Spiel hat keine Wesen.", "Questo gioco non ha nature.", "このゲームにせいかくはありません。", "이 게임에는 성격이 없습니다.", "Este jogo não tem naturezas."),
        ["Naturaleza neutra: no modifica estadísticas."] = ("Neutral nature: stats don’t change.", "中性性格：不影响能力。", "Nature neutre : ne modifie pas les statistiques.", "Neutrales Wesen: verändert keine Statuswerte.", "Natura neutra: non modifica le statistiche.", "無補正のせいかく：ステータスは変わりません。", "중립 성격: 능력치가 변하지 않습니다.", "Natureza neutra: não altera as estatísticas."),
        ["{0}: todas las estadísticas al máximo."] = ("{0}: every stat at its maximum.", "{0}：所有能力均为最大。", "{0} : toutes les statistiques au maximum.", "{0}: alle Statuswerte auf Maximum.", "{0}: tutte le statistiche al massimo.", "{0}：すべてのステータスが最大です。", "{0}: 모든 능력치가 최대입니다.", "{0}: todas as estatísticas no máximo."),

        // Moves tab
        ["Movimientos"] = ("Moves", "招式", "Capacités", "Attacken", "Mosse", "わざ", "기술", "Movimentos"),
        ["Movimiento {0}"] = ("Move {0}", "招式 {0}", "Capacité {0}", "Attacke {0}", "Mossa {0}", "わざ {0}", "기술 {0}", "Movimento {0}"),
        ["— Sin movimiento —"] = ("— No move —", "— 无招式 —", "— Aucune capacité —", "— Keine Attacke —", "— Nessuna mossa —", "— わざなし —", "— 기술 없음 —", "— Sem movimento —"),
        ["Escribe parte del nombre para buscar. Enter confirma y Esc cancela.\nLa lista incluye los movimientos de este juego para el Pokémon, junto con los que ya conoce."] = ("Type part of a name to search. Enter confirms and Esc cancels.\nThe list has this Pokémon’s moves in this game, along with the ones it already knows.", "输入名称的一部分进行搜索。Enter 确认，Esc 取消。\n列表包含这只宝可梦在此游戏中的招式，以及它已学会的招式。", "Tapez une partie du nom pour chercher. Entrée confirme et Échap annule.\nLa liste contient les capacités de ce Pokémon dans ce jeu, ainsi que celles qu’il connaît déjà.", "Gib einen Teil des Namens ein, um zu suchen. Enter bestätigt, Esc bricht ab.\nDie Liste enthält die Attacken dieses Pokémon in diesem Spiel und die, die es bereits kennt.", "Digita parte del nome per cercare. Invio conferma ed Esc annulla.\nL’elenco comprende le mosse di questo Pokémon in questo gioco e quelle che conosce già.", "名前の一部を入力して検索します。Enter で確定、Esc でキャンセルします。\nこのゲームでこのポケモンが使えるわざと、すでに覚えているわざが一覧に表示されます。", "이름의 일부를 입력해 검색하세요. Enter로 확정하고 Esc로 취소합니다.\n목록에는 이 게임에서 이 포켓몬이 쓸 수 있는 기술과 이미 아는 기술이 포함됩니다.", "Digite parte do nome para buscar. Enter confirma e Esc cancela.\nA lista traz os movimentos deste Pokémon neste jogo, junto com os que ele já conhece."),
        ["{0} movimientos compatibles para {1}.\nEscribe el nombre o una parte en cualquier casilla para buscar."] = ("{0} compatible moves for {1}.\nType a name or part of it in any box to search.", "{1} 有 {0} 个可用招式。\n在任意输入框中输入名称或部分名称即可搜索。", "{0} capacités compatibles pour {1}.\nTapez le nom ou une partie du nom dans n’importe quelle case pour chercher.", "{0} kompatible Attacken für {1}.\nGib in ein beliebiges Feld den Namen oder einen Teil davon ein, um zu suchen.", "{0} mosse compatibili per {1}.\nDigita il nome o parte di esso in una casella qualsiasi per cercare.", "{1} が使えるわざは {0}個です。\nどの欄でも名前またはその一部を入力すると検索できます。", "{1}이(가) 쓸 수 있는 기술 {0}개.\n아무 칸에나 이름이나 그 일부를 입력해 검색하세요.", "{0} movimentos compatíveis para {1}.\nDigite o nome ou parte dele em qualquer campo para buscar."),

        // Held item and friendship
        ["Solo megapiedras"] = ("Mega Stones only", "仅超级石", "Méga-Gemmes seulement", "Nur Mega-Steine", "Solo megapietre", "メガストーンのみ", "메가스톤만", "Só Megapedras"),
        ["Objeto actual: {0}"] = ("Current item: {0}", "当前道具：{0}", "Objet actuel : {0}", "Aktuelles Item: {0}", "Strumento attuale: {0}", "現在のどうぐ：{0}", "현재 도구: {0}", "Item atual: {0}"),
