        // Validation
        ["Cada {0} debe estar entre 0 y {1}."] = ("Each {0} must be between 0 and {1}.", "每项{0}必须在 0 到 {1} 之间。", "Chaque {0} doit être entre 0 et {1}.", "Jeder {0}-Wert muss zwischen 0 und {1} liegen.", "Ogni {0} deve essere tra 0 e {1}.", "{0}はそれぞれ 0 から {1} の間にしてください。", "각 {0}은(는) 0에서 {1} 사이여야 합니다.", "Cada {0} deve estar entre 0 e {1}."),
        ["{0}: los EV suman {1}. El máximo es {2}."] = ("{0}: EVs add up to {1}. The maximum is {2}.", "{0}：努力值合计 {1}，上限为 {2}。", "{0} : les EV totalisent {1}. Le maximum est {2}.", "{0}: Die EV ergeben zusammen {1}. Das Maximum ist {2}.", "{0}: gli EV sommano {1}. Il massimo è {2}.", "{0}：努力値の合計が {1} です。上限は {2} です。", "{0}: 노력치 합계가 {1}입니다. 최대는 {2}입니다.", "{0}: os EVs somam {1}. O máximo é {2}."),
