        ["Surtido variocolor"] = ("Shiny assortment", "异色什锦", "Assortiment chromatique", "Schiller-Sortiment", "Assortimento cromatico", "かがやきパワー詰め合わせ", "반짝반짝 파워 모음", "Sortimento brilhante"),
        ["Son del DLC Megadimensión. Los nuevos son de cinco estrellas y llevan los poderes que elijas."] = ("They belong to the Mega Dimension DLC. New ones have five stars and the powers you choose.", "这是“超次元”DLC 的内容。新甜甜圈为五星，并带有你选择的能力。", "Ils font partie du DLC Méga-Dimension. Les nouveaux ont cinq étoiles et les pouvoirs choisis.", "Sie gehören zum DLC Mega-Dimension. Neue haben fünf Sterne und die Kräfte, die du wählst.", "Fanno parte del DLC Megadimensione. Le nuove hanno cinque stelle e i poteri che scegli.", "追加コンテンツ「M次元ラッシュ」の要素です。新しいドーナツは星 5つで、選んだパワーが付きます。", "DLC ‘M차원 러시’의 콘텐츠입니다. 새 도넛은 별 5개이며 선택한 파워가 붙습니다.", "São do DLC Mega Dimension. Os novos têm cinco estrelas e os poderes que você escolher."),
        ["Dónuts en el bolsillo: {0} de {1}"] = ("Donuts in the pocket: {0} of {1}", "口袋中的甜甜圈：{0} / {1}", "Beignets dans la poche : {0} sur {1}", "Donuts in der Tasche: {0} von {1}", "Ciambelle nella tasca: {0} di {1}", "ポケットのドーナツ：{0} / {1}", "주머니의 도넛: {0} / {1}", "Donuts no bolso: {0} de {1}"),
        ["Esta partida no tiene bolsillo de dónuts."] = ("This save has no donut pocket.", "此存档没有甜甜圈口袋。", "Cette partie n’a pas de poche à beignets.", "Dieser Spielstand hat keine Donut-Tasche.", "Questa partita non ha la tasca delle ciambelle.", "このセーブデータにはドーナツのポケットがありません。", "이 세이브에는 도넛 주머니가 없습니다.", "Este save não tem bolso de donuts."),
        ["No reconozco dónde guarda esta partida los dónuts, así que no se pueden editar."] = ("I can't tell where this save keeps its donuts, so they can't be edited.", "无法确定此存档保存甜甜圈的位置，因此不能编辑。", "Impossible de savoir où cette partie garde ses beignets : ils ne peuvent pas être modifiés.", "Ich erkenne nicht, wo dieser Spielstand die Donuts speichert, daher können sie nicht bearbeitet werden.", "Non riconosco dove questa partita conserva le ciambelle, quindi non si possono modificare.", "このセーブデータのドーナツの保存場所を特定できないため、編集できません。", "이 세이브가 도넛을 어디에 저장하는지 확인할 수 없어 편집할 수 없습니다.", "Não reconheço onde este save guarda os donuts, por isso eles não podem ser editados."),
        ["No reconozco dónde guarda esta partida los objetos del mapa, así que no se pueden recoger."] = ("I can't tell where this save keeps its map items, so they can't be collected.", "无法确定此存档保存地图道具的位置，因此不能收集。", "Impossible de savoir où cette partie garde les objets de la carte : ils ne peuvent pas être ramassés.", "Ich erkenne nicht, wo dieser Spielstand die Items der Karte speichert, daher können sie nicht eingesammelt werden.", "Non riconosco dove questa partita conserva gli strumenti della mappa, quindi non si possono raccogliere.", "このセーブデータのマップ上のどうぐの保存場所を特定できないため、回収できません。", "이 세이브가 맵의 도구를 어디에 저장하는지 확인할 수 없어 수집할 수 없습니다.", "Não reconheço onde este save guarda os itens do mapa, por isso eles não podem ser coletados."),
        ["{0} dónuts preparados."] = ("{0} donuts prepared.", "已准备 {0} 个甜甜圈。", "{0} beignets préparés.", "{0} Donuts vorbereitet.", "{0} ciambelle preparate.", "ドーナツを {0}個準備しました。", "도넛 {0}개를 준비했습니다.", "{0} donuts preparados."),
        ["{0} quitado."] = ("{0} removed.", "已移除{0}。", "{0} retiré.", "{0} entfernt.", "{0} tolto.", "{0} を取り除きました。", "{0}을(를) 제거했습니다.", "{0} removido."),
        ["Elige entre 1 y {0} poderes."] = ("Choose between 1 and {0} powers.", "请选择 1 到 {0} 个能力。", "Choisissez entre 1 et {0} pouvoirs.", "Wähle zwischen 1 und {0} Kräften.", "Scegli tra 1 e {0} poteri.", "パワーは 1 から {0}個選んでください。", "파워를 1개에서 {0}개까지 고르세요.", "Escolha entre 1 e {0} poderes."),
        ["Un dónut no puede repetir un poder."] = ("A donut can't repeat a power.", "同一个甜甜圈不能有重复的能力。", "Un beignet ne peut pas répéter un pouvoir.", "Ein Donut kann keine Kraft doppelt haben.", "Una ciambella non può ripetere un potere.", "1つのドーナツに同じパワーは付けられません。", "도넛 하나에 같은 파워를 넣을 수 없습니다.", "Um donut não pode repetir um poder."),
        ["Indica cuántos dónuts quieres agregar."] = ("Say how many donuts to add.", "请指定要添加的甜甜圈数量。", "Indiquez combien de beignets ajouter.", "Gib an, wie viele Donuts du hinzufügen möchtest.", "Indica quante ciambelle vuoi aggiungere.", "追加するドーナツの数を指定してください。", "추가할 도넛 수를 입력하세요.", "Indique quantos donuts deseja adicionar."),
        ["El bolsillo de dónuts está lleno."] = ("The donut pocket is full.", "甜甜圈口袋已满。", "La poche à beignets est pleine.", "Die Donut-Tasche ist voll.", "La tasca delle ciambelle è piena.", "ドーナツのポケットがいっぱいです。", "도넛 주머니가 가득 찼습니다.", "O bolso de donuts está cheio."),
