        ["Los puntos deben estar entre 0 y {0:N0}."] = ("Points must be between 0 and {0:N0}.", "点数必须在 0 到 {0:N0} 之间。", "Les points doivent être compris entre 0 et {0:N0}.", "Die Punkte müssen zwischen 0 und {0:N0} liegen.", "I punti devono essere tra 0 e {0:N0}.", "ポイントは 0 から {0:N0} の間にしてください。", "포인트는 0에서 {0:N0} 사이여야 합니다.", "Os pontos devem estar entre 0 e {0:N0}."),
