        ["{0}: tienes {1}. Quedan {2} por recoger."] = ("{0}: you have {1}. {2} left to collect.", "{0}：你有 {1} 个，还有 {2} 个可收集。", "{0} : vous en avez {1}. Reste {2} à ramasser.", "{0}: Du hast {1}. Noch {2} einzusammeln.", "{0}: ne hai {1}. Ne restano {2} da raccogliere.", "{0}：{1}個所持。回収できるのはあと {2}個です。", "{0}: {1}개 보유. 수집할 수 있는 수량은 {2}개입니다.", "{0}: você tem {1}. Faltam {2} para coletar."),
        ["{0}: tendrás {1} al guardar."] = ("{0}: you'll have {1} after saving.", "{0}：保存后将有 {1} 个。", "{0} : vous en aurez {1} après l’enregistrement.", "{0}: Nach dem Speichern hast du {1}.", "{0}: ne avrai {1} dopo il salvataggio.", "{0}：保存すると {1}個になります。", "{0}: 저장하면 {1}개가 됩니다.", "{0}: você terá {1} ao salvar."),
        ["MT del mapa: quedan {0} por recoger."] = ("TMs on the map: {0} left to collect.", "地图上的招式学习器：还有 {0} 个可收集。", "CT sur la carte : reste {0} à ramasser.", "TM auf der Karte: noch {0} einzusammeln.", "MT sulla mappa: ne restano {0} da raccogliere.", "マップ上のわざマシン：回収できるのはあと {0}個です。", "맵의 기술머신: 수집할 수 있는 수량은 {0}개입니다.", "MTs no mapa: faltam {0} para coletar."),
        ["MT del mapa: se recogerán {0} al guardar."] = ("TMs on the map: {0} will be collected when saving.", "地图上的招式学习器：保存时将收集 {0} 个。", "CT sur la carte : {0} seront ramassées à l’enregistrement.", "TM auf der Karte: {0} werden beim Speichern eingesammelt.", "MT sulla mappa: ne verranno raccolte {0} al salvataggio.", "マップ上のわざマシン：保存時に {0}個回収します。", "맵의 기술머신: 저장할 때 {0}개를 수집합니다.", "MTs no mapa: {0} serão coletadas ao salvar."),
        ["Quedan fuera las zonas que aún no visitas: la partida todavía no las tiene."] = ("Areas you haven't visited are left out: the save doesn't have them yet.", "尚未到访的区域不包括在内：存档中还没有这些区域的数据。", "Les zones pas encore visitées sont exclues : la partie ne les contient pas encore.", "Noch nicht besuchte Gebiete fehlen: Der Spielstand enthält sie noch nicht.", "Le zone non ancora visitate sono escluse: la partita non le contiene ancora.", "まだ訪れていないエリアは含まれません。セーブデータにまだないためです。", "아직 방문하지 않은 지역은 제외됩니다. 세이브에 아직 없기 때문입니다.", "As áreas que você ainda não visitou ficam de fora: o save ainda não as contém."),
